<div class="page-heading"><div><div class="eyebrow">PROGRESIÓN / RUTINAS</div><h1>Plan de <em>entrenamiento</em></h1><p><?=isCoach()?'Asigna y supervisa objetivos individuales.':'Consulta tus tareas y registra tu progreso.'?></p></div></div><?php if(isCoach()):?><section class="panel"><div class="panel-head"><h2>Asignar nueva rutina</h2></div><form method="post" action="<?=e(url('entrenamiento-guardar'))?>" class="form-stack"><?=csrfField()?><div class="form-grid"><label>Jugador<select name="id_jugador" required><option value="">Seleccionar jugador</option><?php foreach($players as $p):?><option value="<?=e($p['id_usuario'])?>"><?=e($p['nickname_valorant'])?></option><?php endforeach;?></select></label><label>Fecha límite<input type="date" name="fecha_limite" required></label></div><label>Título<input name="titulo_rutina" maxlength="150" placeholder="Ej. Revisión de VOD" required></label><label>Descripción<textarea name="descripcion_rutina" rows="3" required></textarea></label><div><button class="btn btn-primary">Asignar rutina →</button></div></form></section><?php endif;?><section class="panel"><div class="panel-head"><h2><?=isCoach()?'Todas las rutinas':'Mis rutinas asignadas'?></h2><span class="meta-tag"><?=count($items)?> REGISTROS</span></div><div class="task-list"><?php foreach($items as $t):?><article class="task"><div class="task-indicator <?=e(strtolower($t['estado']))?>"></div><div class="task-content"><div class="task-top"><h3><?=e($t['titulo_rutina'])?></h3><span class="chip <?=e(strtolower($t['estado']))?>"><?=e($t['estado'])?></span></div><p class="preline"><?=e($t['descripcion_rutina'])?></p><small><?=isCoach()?'Jugador: '.e($t['jugador']).' · ':''?>Límite: <?=e($t['fecha_limite'])?> · Coach: <?=e($t['coach'])?></small></div><div class="task-actions"><?php if(!isCoach()&&$t['estado']==='Pendiente'):?><form method="post" action="<?=e(url('entrenamiento-completar'))?>"><?=csrfField()?><input type="hidden" name="id" value="<?=e($t['id_entrenamiento'])?>"><button class="btn btn-primary small">Marcar completada</button></form><?php endif;?><?php if(isCoach()):?><form method="post" action="<?=e(url('entrenamiento-eliminar'))?>" data-confirm="¿Eliminar esta rutina?"><?=csrfField()?><input type="hidden" name="id" value="<?=e($t['id_entrenamiento'])?>"><button class="btn small danger">Eliminar</button></form><?php endif;?></div></article><?php endforeach;?><?php if(!$items):?><p>No hay rutinas disponibles.</p><?php endif;?></div></section>
